function parseReadme(md){const categories=[];let current=null;for(const line of md.split('\n')){if(/^####\s/.test(line)){const name=line.replace(/^####\s+(?:Build your own\s+)?/i,'').replace(/`/g,'').trim();current={name,tutorials:[]};categories.push(current);continue}if(/^##\s/.test(line)){current=null;continue}if(!current)continue;const m=line.match(/^\s*[*-]\s+\[\*\*(.+?)\*\*:\s*(.*?)\s*\]\((https?:\/\/.+)\)(.*)$/);if(m){const url=m[3].split(') [')[0];current.tutorials.push({language:m[1],languages:m[1].split(/\s*\/\s*/),title:m[2].replace(/^_|_$/g,''),url,video:/\[video\]/i.test(m[4])})}}return categories.filter(c=>c.tutorials.length)}
if(typeof module!=='undefined')module.exports={parseReadme};
